Item.method_code:
Innovator innovator = this.getInnovator();

string favoriteId = this.getProperty("id");

Item favoriteItemToDelete = innovator.newItem("Favorite", "get");
favoriteItemToDelete.setAttribute("select", "category,additional_data");
favoriteItemToDelete.setID(favoriteId);
favoriteItemToDelete = favoriteItemToDelete.apply();
if (favoriteItemToDelete.isError())
{
	return favoriteItemToDelete;
}

string categoryItemId = string.Empty;
Newtonsoft.Json.Linq.JObject additionalData = null;
string favoriteCategory = favoriteItemToDelete.getProperty("category");
string additionalDataJson = favoriteItemToDelete.getProperty("additional_data");
if ((favoriteCategory == "Search" || favoriteCategory == "Grid Layout") && !string.IsNullOrEmpty(additionalDataJson))
{
	try
	{
		additionalData = Newtonsoft.Json.Linq.JObject.Parse(additionalDataJson);
		categoryItemId = additionalData.Value<string>("id");
	}
	catch (Newtonsoft.Json.JsonReaderException)
	{
	}
}

string layoutId = null;
if (favoriteCategory == "Search") {
	favoriteCategory = "SavedSearch";
	if (additionalData?["layout_id"] != null)
	{
		layoutId = additionalData.Value<string>("layout_id");
	}
}

if (!string.IsNullOrEmpty(layoutId))
{
	Item layoutItemToDelete = innovator.newItem("Grid Layout", "delete");
	layoutItemToDelete.setID(layoutId);
	layoutItemToDelete = layoutItemToDelete.apply();
	if (layoutItemToDelete.isError())
	{
		return layoutItemToDelete;
	}
}

favoriteItemToDelete.setAttribute("action", "delete");
favoriteItemToDelete = favoriteItemToDelete.apply();
if (favoriteItemToDelete.isError() || string.IsNullOrEmpty(categoryItemId))
{
	return favoriteItemToDelete;
}


Item categoryItemToDelete = innovator.newItem(favoriteCategory, "delete");
categoryItemToDelete.setID(categoryItemId);
categoryItemToDelete = categoryItemToDelete.apply();

return categoryItemToDelete.isError() ? categoryItemToDelete : favoriteItemToDelete;
